// Living portraits (src/livegen.ts): the photo test and the prompt-version remake.
// 2026-11-03: Mike "I have not seen living profiles on Caldera". Black-and-white portraits were skipped as "not a photo",
// and loops from prompt v1 barely moved (peak ~3/255). No network: fal is mocked, images are generated by ffmpeg.
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { DatabaseSync } from "node:sqlite";
import { build } from "esbuild";
import { after as __afterAll } from "node:test";
const __tmpDirs = [];
const __mkdtemp = (p) => { const d = fs.mkdtempSync(p); __tmpDirs.push(d); return d; };
__afterAll(() => { for (const d of __tmpDirs) fs.rmSync(d, { recursive: true, force: true }); });   // temp hubs are removed after the file's tests, even when one fails

const tmp = __mkdtemp(path.join(os.tmpdir(), "cal-livegen-"));
const out = path.join(tmp, "livegen.mjs");
await build({ entryPoints: [new URL("../src/livegen.ts", import.meta.url).pathname], bundle: true, platform: "node", format: "esm", packages: "external", outfile: out, logLevel: "error" });
const { liveGen, looksLikePhoto, isGreyThumb } = await import(out);

const ff = (args) => execFileSync("ffmpeg", ["-loglevel", "error", "-y", ...args]);
const thumb = (f) => ff(["-i", f, "-vf", "scale=32:32", "-frames:v", "1", "-f", "rawvideo", "-pix_fmt", "rgb24", "pipe:1"]);
// a grey image with a photo's spread of tones (ffmpeg's test pattern in greyscale); a two-tone identicon; a grey two-tone
// logo; a colour image
const bw = path.join(tmp, "bw.png"), icon = path.join(tmp, "icon.png"), greyLogo = path.join(tmp, "greylogo.png"), color = path.join(tmp, "color.png");
ff(["-f", "lavfi", "-i", "testsrc2=s=256x256,format=gray", "-frames:v", "1", bw]);
ff(["-f", "lavfi", "-i", "color=c=0xeeeeee:s=256x256", "-vf", "drawbox=x=64:y=64:w=128:h=64:color=0x222222:t=fill,drawbox=x=96:y=160:w=64:h=64:color=0x222222:t=fill", "-frames:v", "1", greyLogo]);
ff(["-f", "lavfi", "-i", "color=c=0xeeeeee:s=256x256", "-vf", "drawbox=x=64:y=64:w=128:h=64:color=0x66cc44:t=fill,drawbox=x=96:y=160:w=64:h=64:color=0x66cc44:t=fill", "-frames:v", "1", icon]);
ff(["-f", "lavfi", "-i", "testsrc2=s=256x256", "-frames:v", "1", color]);

test("black-and-white photos count as photos; identicons don't", () => {
  assert.equal(looksLikePhoto(thumb(bw)), true);
  assert.equal(looksLikePhoto(thumb(color)), true);
  assert.equal(looksLikePhoto(thumb(icon)), false);
  assert.equal(looksLikePhoto(thumb(greyLogo)), false);
  assert.equal(isGreyThumb(thumb(bw)), true, "a grey photo's loop is kept grey");
  assert.equal(isGreyThumb(thumb(color)), false);
});

test("loops from an older prompt are remade once (owner first), a failed remake keeps the working loop, young profiles wait", async () => {
  process.env.FAL_KEY = "test";
  const posts = []; const realFetch = globalThis.fetch;
  globalThis.fetch = async (_u, o) => { posts.push(JSON.parse(o?.body || "{}")); return { ok: false, status: 503, text: async () => "mock down" }; };
  try {
    const db = new DatabaseSync(":memory:"), dir = __mkdtemp(path.join(tmp, "data-")), logs = [];
    const mk = () => liveGen({ db, dataDir: dir, log: (s) => logs.push(s), isModerated: () => false });
    const L = mk(), old = new Date(Date.now() - 30 * 864e5).toISOString();
    for (const h of ["alice", "mike"]) { const f = L.files(h); fs.mkdirSync(path.dirname(f.mp4), { recursive: true }); fs.writeFileSync(f.mp4, "x"); fs.writeFileSync(f.webp, "x"); }
    // first pass makes rows (fal down -> failed); then pretend both are ready v1 loops
    L.check("alice", "img/a.png", bw, old); L.check("mike", "img/m.png", color, old);
    await new Promise((r) => setTimeout(r, 2500));
    assert.match(posts[0]?.prompt || "", /clearly comes alive/);
    db.prepare("UPDATE live_portraits SET status='ready', prompt_v=NULL, err=NULL, tries=0").run();
    posts.length = 0; logs.length = 0;
    const L2 = mk(); L2.check("alice", "img/a.png", bw, old); L2.check("mike", "img/m.png", color, old);
    await new Promise((r) => setTimeout(r, 2500));
    assert.equal(posts.length, 2, "both v1 loops get a remake");
    assert.deepEqual(db.prepare("SELECT status FROM live_portraits ORDER BY handle").all().map((r) => r.status), ["ready", "ready"], "a failed remake keeps the ready loop");
    assert.ok(logs.some((l) => /remake failed; keeping the current loop/.test(l)));
    posts.length = 0; L2.check("mike", "img/m.png", color, old); await new Promise((r) => setTimeout(r, 300));
    assert.equal(posts.length, 0, "a failed remake isn't retried in the same process");
    db.prepare("UPDATE live_portraits SET prompt_v=2 WHERE handle='mike'").run();
    const m = mk().map(); assert.match(m.mike.v, /-p2-[0-9a-z]+$/, "the cache key moves with the prompt and the file"); assert.doesNotMatch(m.alice.v, /-p\d/);
    posts.length = 0; mk().check("alice", "img/a.png", bw, new Date().toISOString()); await new Promise((r) => setTimeout(r, 300));
    assert.equal(posts.length, 0, "profiles under 24h old wait");
  } finally { globalThis.fetch = realFetch; delete process.env.FAL_KEY; }
});
